\documentclass{article}
\usepackage{CJKutf8}
\title{Personalized Federated Learning with Local Adaptation}
\author{Anon}
\begin{document}
\maketitle
\begin{abstract}
Federated learning trains a shared model across decentralized devices without exchanging raw data. However, statistical heterogeneity across clients degrades the performance of the global model on individual devices. We propose a personalized federated learning algorithm that adapts the global model to each client through a lightweight local adaptation layer. Experiments on four benchmarks show that our method improves average client accuracy by 6 percent over strong baselines while keeping communication costs unchanged.
\end{abstract}
\section{Introduction}
Federated learning enables collaborative model training under privacy constraints.
\end{document}
